:new01","key":{"work_id":976100101,"language":"nl"},"before":null,"after":{"work_id":976100101,"language":"nl","bound_author_id":976300008,"text":"Lies verlaat eind jaren zeventig haar ouderlijk huis en gaat in Amsterdam studeren. De vrijheid van haar nieuwe omgeving staat tegenover het geloof waarmee ze is opgegroeid. Een ontmoeting met een oud boek verbindt haar zoektocht met die van Richardis von Stade en Hildegard von Bingen in de twaalfde eeuw. De roman legt hun verschillende werelden naast elkaar en onderzoekt hoe vrouwen ruimte zoeken voor kennis, overtuiging en een eigen leven.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/2127115/terug-naar-hildegard.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-05-20261101","evidence":[{"url":"https://metadata.isbn.nl/2127115/terug-naar-hildegard.html","checkedAt":"2026-11-01","fact":"Source content actually read; original Dutch synopsis, identity reviewed separately","sha256":"16b7206470d5f8fe740e4a44d06f83a2367efcadde92c56928e7ec58137a5619"}]}},{"relation":"works","ref":"work:new02","key":{"id":976100102},"before":null,"after":{"title":"Dog Man: Big Jim Believes","author_id":930300098,"first_publish_year":2025,"source_type":"lumiscore_native","native_identity_key":"nl-reviewed-isbn:9789493474758","work_type":null,"open_library_id":null,"id":976100102}},{"relation":"editions","ref":"edition:9789493474758","key":{"id":976200138},"before":null,"after":{"work_id":976100102,"title":"Dog Man 14 - Dog Man: Dank voor stank","isbn_13":"9789493474758","isbn_10":null,"language":"nld","publisher":"WPG Kindermedia","open_library_edition_id":null,"id":976200138}},{"relation":"catalog_edition_metadata","ref":"metadata:9789493474758","key":{"edition_id":"@edition:9789493474758"},"before":null,"after":{"edition_id":"@edition:9789493474758","work_i