,"after":{"work_id":976100102,"language":"nl","bound_author_id":930300098,"text":"Dog Man en zijn bondgenoten krijgen opnieuw te maken met de Ruimteschatjes uit de Ruimte. Hun plannen veranderen de stad en brengen ook vertrouwde personages in een ongewone situatie. Kapitein Cupcake zoekt een manier om de dreiging samen met de anderen te weerstaan, terwijl Opa weinig vertrouwen heeft in een goede afloop. In dit veertiende stripavontuur spelen samenwerken en het beoordelen van schijnbaar onmogelijke mogelijkheden een belangrijke rol.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/2095315/dog-man-14-dog-man-dank-voor-stank.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-05-20261101","evidence":[{"url":"https://metadata.isbn.nl/2095315/dog-man-14-dog-man-dank-voor-stank.html","checkedAt":"2026-11-01","fact":"Source content actually read; original Dutch synopsis, identity reviewed separately","sha256":"42e13916a9004a37da7173b95692fd2e6e3af63444668321f8c1d73baa2c4030"}]}},{"relation":"works","ref":"work:new03","key":{"id":976100103},"before":null,"after":{"title":"Texel","author_id":976300009,"first_publish_year":null,"source_type":"lumiscore_native","native_identity_key":"nl-reviewed-isbn:9789401626309","work_type":null,"open_library_id":null,"id":976100103}},{"relation":"editions","ref":"edition:9789401626309","key":{"id":976200139},"before":null,"after":{"work_id":976100103,"title":"Texel","isbn_13":"9789401626309","isbn_10":null,"language":"nld","publisher":"Xander Uitgevers B.V.","open_library_edition_id":null,"id":976200139}},{"relation":"catalog_edition_metadata","ref":"metadata:9789401626309","key":{"edition_id":"@edition:9789401626309"},"before":null,"after":{"edition_id":"@edition:9789401626309","work_id":976100103,"bound_author_id":976300009,"bound_title":"Texel","bound_lan