"checkedAt":"2026-11-01","sha256":"cf8c55caf69edeb092f5435b2488bdd668f18ec432146a58e34b2854c508f452","bytes":51437,"fact":"Same-edition source association and title/author artwork visually reviewed; not only HTTP200"}]}},{"relation":"catalog_work_descriptions","ref":"description:new07","key":{"work_id":976100107,"language":"nl"},"before":null,"after":{"work_id":976100107,"language":"nl","bound_author_id":976300013,"text":"Paulien Cornelisse onderzoekt woorden die in alledaagse gesprekken zo vanzelfsprekend zijn dat hun betekenis gemakkelijk onopgemerkt blijft. Ze kijkt onder meer naar korte toevoegingen die de toon van een zin veranderen zonder veel aandacht te vragen. Vanuit zulke kleine taalobservaties verkent zij wat mensen met hun woorden duidelijk maken en wat juist onuitgesproken blijft. Het essay draait niet om voorschriften voor correct Nederlands, maar om nieuwsgierig kijken naar het gebruik ervan.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/2047041/hehe.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-05-20261101","evidence":[{"url":"https://metadata.isbn.nl/2047041/hehe.html","checkedAt":"2026-11-01","fact":"Source content actually read; original Dutch synopsis, identity reviewed separately","sha256":"72f46208ef4f187c325c4e254e4a9266f74fade6e749967b116afc2736ccaef3"}]}},{"relation":"works","ref":"work:new08","key":{"id":976100108},"before":null,"after":{"title":"Vertel onze kinderen hoeveel ik van ze hou","author_id":976300014,"first_publish_year":null,"source_type":"lumiscore_native","native_identity_key":"nl-reviewed-isbn:9789021065915","work_type":null,"open_library_id":null,"id":976100108}},{"relation":"editions","ref":"edition:9789021065915","key":{"id":976200144},"before":null,"after":{"work_id":976100108,"title":"Vertel onze kinderen hoeveel ik van ze hou","i